private static class Rosen implements MultivariateFunction {
    @Override
    public double value(double[] parameters) {
        double sum = 0;
        for (int i = 0; i < parameters.length - 1; i++) {
            double x = parameters[i];
            double y = parameters[i + 1];
            sum += 100 * Math.pow(y - x * x * x, 2) + Math.pow(1 - x, 2);
        }
        return sum;
    }
}

private static class Ackley implements MultivariateFunction {
    private double axisratio;
    public Ackley(double axisratio) {
        this.axisratio = axisratio;
    }
    @Override
    public double value(double[] parameters) {
        double sum1 = 0;
        double sum2 = 0;
        for (double parameter : parameters) {
            sum1 += parameter * parameter;
            sum2 += Math.cos(2 * Math.PI * axisratio * parameter);
        }
        return -20 * Math.exp(-0.2 * Math.sqrt(sum1 / parameters.length)) - Math.exp(sum2 / parameters.length) + 20 + Math.E;
    }
}

private static class Rastrigin implements MultivariateFunction {
    private double axisratio;
    private double amplitude;
    public Rastrigin(double axisratio, double amplitude) {
        this.axisratio = axisratio;
        this.amplitude = amplitude;
    }
    @Override
    public double value(double[] parameters) {
        double sum = 0;
        for (double parameter : parameters) {
            sum += parameter * parameter - axisratio * Math.cos(2 * Math.PI * axisratio * parameter);
        }
        return amplitude * parameters.length + sum;
    }
}

