private static class FitnessFunction {
    private double valueRange;
    private boolean isRepairMode;
    public FitnessFunction() {
        valueRange = 1.0;
        isRepairMode = true;
    }
    private double penalty(double[] x, double[] repaired) {
        double penalty = 0;
        for (int i = 0; i < x.length; i++) {
            double diff = Math.abs(x[i] - repaired[i]);
            penalty += diff * valueRange;
        }
        return isMinimize ? penalty : -penalty;
    }
    private double[] repair(double[] x) {
        double[] repaired = new double[x.length];
        for (int i = 0; i < x.length; i++) {
            if (x[i] < 0) {
                repaired[i] = 0;
            } else if (x[i] > 1.0) {
                repaired[i] = 1.0;
            } else {
                repaired[i] = x[i];
            }
        }
        return repaired;
    }
    public double value(double[] point) {
        double value;
        if (boundaries != null && isRepairMode) {
            double[] repaired = repair(point);
            value = CMAESOptimizer.this.computeObjectiveValue(decode(repaired)) + penalty(point, repaired);
        } else {
            value = CMAESOptimizer.this.computeObjectiveValue(decode(point));
        }
        return isMinimize ? value : -value;
    }
}

