private static class Array2DRowRealMatrix extends RealMatrix {
    private double[][] data;
    public Array2DRowRealMatrix(double[][] data) {
        this.data = data;
    }
    public double getEntry(int row, int column) {
        return data[row][column];
    }
    public int getRowDimension() {
        return data.length;
    }
    public int getColumnDimension() {
        return data[0].length;
    }
    public RealMatrix transpose() {
        double[][] transpose = new double[columnDimension][rowDimension];
        for (int i = 0; i < rowDimension; i++) {
            for (int j = 0; j < columnDimension; j++) {
                transpose[j][i] = data[i][j];
            }
        }
        return new Array2DRowRealMatrix(transpose, false);
    }
    public RealMatrix scalarMultiply(double scalar) {
        double[][] result = new double[rowDimension][columnDimension];
        for (int i = 0; i < rowDimension; i++) {
            for (int j = 0; j < columnDimension; j++) {
                result[i][j] = data[i][j] * scalar;
            }
        }
        return new Array2DRowRealMatrix(result, false);
    }
    public RealMatrix add(RealMatrix m) {
        double[][] result = new double[rowDimension][columnDimension];
        for (int i = 0; i < rowDimension; i++) {
            for (int j = 0; j < columnDimension; j++) {
                result[i][j] = data[i][j] + m.getEntry(i, j);
            }
        }
        return new Array2DRowRealMatrix(result, false);
    }
    public RealMatrix subtract(RealMatrix m) {
        double[][] result = new double[rowDimension][columnDimension];
        for (int i = 0; i < rowDimension; i++) {
            for (int j = 0; j < columnDimension; j++) {
                result[i][j] = data[i][j] - m.getEntry(i, j);
            }
        }
        return new Array2DRowRealMatrix(result, false);
    }
    public RealMatrix multiply(RealMatrix m) {
        double[][] result = new double[rowDimension][m.getColumnDimension()];
        for (int i = 0; i < rowDimension; i++) {
            for (int j = 0; j < m.getColumnDimension(); j++) {
                result[i][j] = 0;
                for (int k = 0; k < columnDimension; k++) {
                    result[i][j] += data[i][k] * m.getEntry(k, j);
                }
            }
        }
        return new Array2DRowRealMatrix(result, false);
    }
    public RealMatrix getSubMatrix(int startRow, int endRow, int startColumn, int endColumn) {
        double[][] subMatrix = new double[endRow - startRow + 1][endColumn - startColumn + 1];
        for (int i = startRow; i <= endRow; i++) {
            System.arraycopy(data[i], startColumn, subMatrix[i - startRow], 0, endColumn - startColumn + 1);
        }
        return new Array2DRowRealMatrix(subMatrix, false);
    }
    public void setSubMatrix(double[][] subMatrix, int row, int column) {
        for (int i = 0; i < subMatrix.length; i++) {
            System.arraycopy(subMatrix[i], 0, data[row + i], column, subMatrix[i].length);
        }
    }
}

